mapper.select:
SELECT business_id, project_id, task_id, expert_run_id, version,
storage_key, file_name, media_type, size_bytes, sha256, status
FROM project_artifact WHERE tenant_id = #{tenantId}
AND project_id = #{projectId} AND business_id = #{id}

SELECT storage_key FROM project_artifact
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND business_id = #{reference} AND status = 'AVAILABLE'

SELECT t.tenant_id, t.business_id AS coordinator_task_id,
#{agentId} AS agent_id, #{agentRunId} AS agent_run_id
FROM coordinator_task t
JOIN coordinator_plan p ON p.business_id = t.plan_id
JOIN project_conversation c ON c.business_id = p.conversation_id
WHERE t.project_id = #{projectId} AND p.conversation_id = #{conversationId}
AND c.session_id = #{businessSessionId} AND t.session_id = #{agentRunId}
AND t.expert_id = #{agentId}
AND t.status IN ('RUNNING', 'WAITING_HUMAN')

SELECT COUNT(*) FROM project_artifact WHERE tenant_id = #{tenantId}
AND project_id = #{projectId} AND task_id = #{coordinatorTaskId}
AND expert_run_id = #{agentRunId} AND business_id = #{artifactId}
AND status = 'AVAILABLE'

SELECT a.storage_key FROM project_artifact a JOIN coordinator_task t ON t.business_id = a.task_id WHERE t.plan_id = #{planId} AND t.task_key IN
#{item}
AND a.status = 'AVAILABLE' ORDER BY a.business_id

