INSERT INTO project_artifact_lineage (output_artifact_id, input_artifact_id) SELECT #{outputArtifactId}, a.business_id FROM project_artifact a JOIN coordinator_task t ON t.business_id = a.task_id WHERE t.plan_id = #{planId} AND t.task_key IN
#{item}
AND a.status = 'AVAILABLE'
